import java.lang.reflect.Modifier;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

public class Main {
    public record Point(int x, int y) {}

    public record Range(int start, int end) {
        public Range {
            if (start > end) {
                throw new IllegalArgumentException("start must <= end");
            }
        }
        public int length() { return end - start; }
    }

    public record UserDto(String name, String email) implements Serializable {
        public UserDto {
            name = Objects.requireNonNull(name).strip();
            email = Objects.requireNonNull(email).toLowerCase(Locale.ROOT);
            if (!email.contains("@")) {
                throw new IllegalArgumentException("invalid email");
            }
        }
        public String displayName() {
            return name.substring(0, 1).toUpperCase(Locale.ROOT) + name.substring(1);
        }
    }

    public record SafeOrder(String id, List<String> items) {
        public SafeOrder {
            id = Objects.requireNonNull(id);
            items = List.copyOf(items);
        }
    }

    public record UnsafeOrder(String id, List<String> items) {}

    public static void main(String[] args) {
        Point p = new Point(3, 5);
        System.out.println("point: " + p + ", x=" + p.x());
        assert p.equals(new Point(3, 5));
        assert Modifier.isFinal(Point.class.getModifiers());
        assert Point.class.getSuperclass() == Record.class;

        Range range = new Range(2, 9);
        System.out.println("range length: " + range.length());
        boolean invalidRange = false;
        try {
            new Range(10, 1);
        } catch (IllegalArgumentException e) {
            invalidRange = true;
        }

        UserDto user = new UserDto(" ada ", "ADA@EXAMPLE.COM");
        System.out.println("user: " + user.name() + "/" + user.email() + ", display=" + user.displayName());

        List<String> source = new ArrayList<>(List.of("book"));
        SafeOrder safe = new SafeOrder("S1", source);
        UnsafeOrder unsafe = new UnsafeOrder("U1", source);
        int unsafeHashBefore = unsafe.hashCode();
        source.add("pen");
        int unsafeHashAfter = unsafe.hashCode();
        System.out.println("safe items: " + safe.items() + ", unsafe items: " + unsafe.items());

        boolean safeItemsImmutable = false;
        try {
            safe.items().add("eraser");
        } catch (UnsupportedOperationException e) {
            safeItemsImmutable = true;
        }

        assert range.length() == 7;
        assert invalidRange;
        assert user.name().equals("ada");
        assert user.email().equals("ada@example.com");
        assert user.displayName().equals("Ada");
        assert safe.items().equals(List.of("book"));
        assert unsafe.items().equals(List.of("book", "pen"));
        assert unsafeHashBefore != unsafeHashAfter;
        assert safeItemsImmutable;
    }
}
